    async fn execute(&self, _ctx: &ToolContext, args: Value) -> (ToolStatus, Value) {
        let path = match args["path"].as_str() {
            Some(path) => expand_tilde(path),
            None => return err("path argument not found"),
        };

        let offset = args["offset"].as_u64().unwrap_or(0) as usize;
        let max_chars = args["max_chars"]
            .as_u64()
            .unwrap_or(DEFAULT_MAX_CHARS)
            .clamp(1, HARD_MAX_CHARS) as usize;

        let file_path = PathBuf::from(&path);
        if !file_path.is_file() {
            return err("File not found or not a file");
        }

        // Read text as-is; fall back to document conversion for non-UTF-8 files.
        let (content, converted) = match fs::read_to_string(&file_path) {
            Ok(text) => (text, false),
            Err(e) if e.kind() == std::io::ErrorKind::InvalidData => {
                match extract_with_xberg(&path).await {
                    Ok(text) => (text, true),
                    Err(e) => return err(e),
                }
            }
            Err(e) => return err(format!("Failed to read file: {e}")),
        };

        let total_len = content.chars().count();
        let start = offset.min(total_len);
        let chunk: String = content.chars().skip(start).take(max_chars).collect();
        let end = start + chunk.chars().count();
        let is_truncated = end < total_len;

        ok(json!({
            "status": "success",
            "path": path,
            "converted": converted,
            "contents": chunk,
            "total_len": total_len,
            "next_offset": if is_truncated { json!(end) } else { json!(null) },
            "is_truncated": is_truncated,
        }))
    }
