async fn extract_with_xberg(path: &str) -> Result<String, String> {
    let extraction_config = ExtractionConfig::default();
    let input = ExtractInput::from_uri(path);
    match xberg::extract(input, &extraction_config).await {
        Ok(extracted) => Ok(extracted.results[0].content.clone()),
        Err(e) => Err(format!("Failed to extract data: {e}")),
    }
}
#[cfg(test)]
mod tests {
    use super::*;

    fn ctx(handle: &crate::agent_loop::AgentHandle) -> ToolContext<'_> {
        ToolContext {
            handle,
            session_id: "test",
        }
    }

    #[tokio::test]
    async fn reads_text_with_offset_chunking() {
        let (_rx, handle) = crate::agent_loop::AgentHandle::new();
        let path = std::env::temp_dir().join(format!(
            "mia-test-{}-read.txt",
            std::process::id()
        ));
        fs::write(&path, "0123456789abcdef").unwrap();

        // First chunk.
        let (status, payload) = FSReadFile
            .execute(&ctx(&handle), json!({ "path": path.to_string_lossy(), "max_chars": 4 }))
            .await;
        assert_eq!(status, ToolStatus::Success);
        assert_eq!(payload["contents"], "0123");
        assert_eq!(payload["total_len"], 16);
        assert_eq!(payload["next_offset"], 4);
        assert_eq!(payload["is_truncated"], true);

        // Second chunk via offset.
        let (status, payload) = FSReadFile
            .execute(&ctx(&handle), json!({ "path": path.to_string_lossy(), "offset": 4, "max_chars": 4 }))
            .await;
        assert_eq!(status, ToolStatus::Success);
        assert_eq!(payload["contents"], "4567");
        assert_eq!(payload["next_offset"], 8);

        // Past the end.
        let (status, payload) = FSReadFile
            .execute(&ctx(&handle), json!({ "path": path.to_string_lossy(), "offset": 20 }))
            .await;
        assert_eq!(status, ToolStatus::Success);
        assert_eq!(payload["contents"], "");
        assert_eq!(payload["next_offset"], Value::Null);
        assert_eq!(payload["is_truncated"], false);

        fs::remove_file(&path).ok();
    }

    #[tokio::test]
    async fn missing_file_is_error() {
        let (_rx, handle) = crate::agent_loop::AgentHandle::new();
        let (status, _payload) = FSReadFile
            .execute(&ctx(&handle), json!({ "path": "/nonexistent/definitely-missing" }))
            .await;
        assert!(matches!(status, ToolStatus::Error(_)));
    }
}
